C[15]=dict(name="Participle and relative clauses for combining ideas",
 notice="<h4>Notice (3 min)</h4><table class='tbl'><tr><th>Two sentences</th><th>One sentence</th></tr><tr><td>The council reviewed the data. It changed its policy.</td><td><b>Having reviewed</b> the data, the council changed its policy.</td></tr><tr><td>Students who live far from campus often arrive late.</td><td>Students <b>living far from campus</b> often arrive late.</td></tr><tr><td>The report, which was published in May, shows…</td><td>The report, <b>published in May</b>, shows…</td></tr></table><p><b>Rule:</b> a participle clause shares the subject of the main clause. <i>-ing</i> = active; <i>-ed</i> = passive; <i>having + -ed</i> = earlier action.</p>",
 trap="<h4>Spanish-speaker trap</h4><p>Spanish uses the gerund freely (<i>Habiendo revisado los datos…</i>), but English needs the same subject in both parts. ✗ <b>Having reviewed</b> the data, the policy changed. ✓ Having reviewed the data, <b>the council</b> changed the policy.</p>",
 choose=[["___ the data, the council changed its policy.","Having reviewed",["Reviewed having","Review","To have review"],"Perfect participle."],["Students ___ far from campus often arrive late.","living",["lived","live they","to live"],"Reduced relative clause."],["The report, ___ in May, shows a rise.","published",["publishing","is published","publish"],"Passive participle."],["___ tired, she went to bed early.","Feeling",["Felt","To feel","Feeled"],"Same subject, active."],["Prices, ___ by inflation, rose again.","driven",["driving","drive","drove"],"Passive."]],
 fte=[["[[Having]] [[review]] the data, [[the council]] changed [[its policy]].",1,"<i>Having reviewed</i>."],["[[Living]] far away, [[the bus]] [[is]] [[slow]] for me.",1,"The subject must match: <i>I find the bus slow</i>."],["The report, [[publishing]] in May, [[shows]] [[a rise]] [[clearly]].",0,"<i>published</i>."],["[[Feeling]] [[tired]], [[the bus]] [[left]] early.",2,"The subject must match: <i>Feeling tired, I took the bus.</i>"],["Prices, [[driven]] [[by]] [[inflation]], [[rises]] again.",3,"<i>rose</i>: the subject is plural and the sentence is in the past."]],
 corr=[["Having review the data, the council changed its policy.","Having reviewed the data, the council changed its policy.",["Having reviewing the data, the council changed its policy.","Have reviewed the data, the council changed its policy.","Having been review the data, the council changed its policy."],"<i>Having + -ed</i>."],["Students lived far from campus often arrive late.","Students living far from campus often arrive late.",["Students who living far from campus often arrive late.","Students lives far from campus often arrive late.","Students to live far from campus often arrive late."],"Reduced clause."],["The report, publishing in May, shows a rise.","The report, published in May, shows a rise.",["The report, publish in May, shows a rise.","The report, which published in May, shows a rise.","The report, was published in May, shows a rise."],"Passive participle."],["Walking home, the rain started.","Walking home, I felt the rain start.",["Walking home, the rain started it.","Walking home, started the rain.","Walking home, it rain started."],"Same subject."]],
 trans=[["Combine: “The council reviewed the data. It changed its policy.”","Having reviewed the data, the council changed its policy.",["Reviewing having the data, the council changed its policy.","Having review the data, the council changed its policy.","The council having reviewed the data it changed its policy."],"Perfect participle."],["Reduce: “Students who live far from campus often arrive late.”","Students living far from campus often arrive late.",["Students who living far from campus often arrive late.","Students lives far from campus often arrive late.","Students live far from campus often arrive late who."],"<i>-ing</i> clause."],["Reduce: “The report, which was published in May, shows a rise.”","The report, published in May, shows a rise.",["The report, publishing in May, shows a rise.","The report, which published in May, shows a rise.","The report published, in May, shows a rise."],"Passive participle."]])
